"""Summarize immutable run outputs without altering success criteria."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[3];A=R/'04_EXPERIMENTS/ADR/ADR-0767-polished-narrative-qualification';D=A/'artifacts';O=D/'run-001'
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def put(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
m=read(A/'실험/manifest.json');r=read(O/'result.json');passed=r['strict_success'];failed=[k for k,v in r['checks'].items() if not v]
table='| 구분 | 근거 결속 응답 | 호출 | 입력 토큰 | 요청시간 합계 |\n|---|---:|---:|---:|---:|\n'
for arm,v in r['by_arm'].items():table+=f"| {arm} | {v['supported']}/{len(v['cases'])} | {v['calls']} | {v['input_tokens']:,} | {v['request_seconds']:.1f}초 |\n"
m['questions']=[]
headings=['실행 메타','사용자 질문 원문','기준답변 — 채점 전용, 제품 입력 비공개','제품 입력을 구성한 원값','제품 모델 호출 — run·arm별 실제 원문','중간 LLM 호출 — router/compiler/verifier/repair','채점 호출과 반복 판정','사례 최종 판정']
review=read(O/'semantic-review.json')
for n,c in enumerate(read(D/'design/dataset.json')['cases'],1):
 p=A/'실험'/f'질문-{n:03}-{c["case_id"]}.md'
 body=['ADR0767/run001; '+c['role'],c['question'],'Frozen ../artifacts/design/gold.json is evaluator-only; no gold enters product context.', '### 회수·탈락 단계 원장 — run·arm별\n\nActual native API; retrieval-ledger.json.gz accounts catalogue/recall/acquired/presented; exact physical views in raw archive.', 'Qwen3.8 Parasail FP8 none/fallback false. Exact request/response/usage retained in raw.tar.gz; restoration and member hashes in raw-archive.json.', 'All calls through ExperimentClient. One request per frozen case/arm, internal retries accounted; no adaptive case rerun.', 'Offline saved-source review, no independent judge model or repeated voting. Structural quote coverage does not certify semantics.', json.dumps(review['cases'][c['case_id']],ensure_ascii=False)]
 p.write_text('# '+c['case_id']+'\n\n'+'\n\n'.join(f'## {i}. {h}\n\n{b}' for i,(h,b) in enumerate(zip(headings,body),1))+'\n');m['questions'].append({'number':n,'case_id':c['case_id'],'file':p.name,'sha256':sha(p)})
put(A/'실험/manifest.json',m)
sections=[('결정 요약',('Accepted: 동결한 공개 검증 기준 통과. 작업 코드·GENOS 반입 자료 준비 대상.' if passed else 'Rejected: '+', '.join(failed))+ ' 로컬 MAIN 포인터 및 GENOS 실제 배포는 별도 상태다.'),('문제와 변경 전 구조','기존 v8는 적용 범위·조건·의무를 고정 표제로 짧게 나열한다. 최종 생성 호출이 없고, 워크플로우는 완료된 본문을 나누어 송신한다.'),('가설과 사전 판정 기준','63개 계약 검사, 새 공개2문항과 기존 과잉단정 회귀1문항. 원문·권한·상태 결속과 명시 양태를 보존하고 미근거 의무·기한·금지를 추가하지 않는다. 쌍별 호출 증가 최대2회, 작성 단계180초 이하. design/criteria.json 및 freeze.json을 호출 전에 동결했다.'),('실험 설계','완료766/narrative/rev003를 상속하고 최종 작성의 일반 지침만 강화했다. 첫 문단 핵심 답변, 이어서 소제목과 구체적 설명·목록. 승인된 모든 판단을 원문과 함께 작성기로 전달한다. 문단의 근거 ID와 문단 구조를 확인한 뒤 생성 도중 표시한다.'),('데이터·모델·재현성','동일 공개65문서와 immutable generation. 6216개 노출 root를 제외한2개 신규 root, 알려진 상법467회귀1개. 모델 Qwen3.8/Parasail FP8/reasoning none/no fallback. 정확한5요청 순서 동결, 결과 후 수정·재실행 없음. 개인정보·사용자 사진 질문·GENOS 내부 데이터의 외부 전송 없음.'),('결과',table+'\n[상세 집계](artifacts/run-001/result.json). 근거 결속 응답은 법률 정답률이 아니다.'),('사례별 오류 분석','[의미 검토](artifacts/run-001/semantic-review.json). 이전766B의 원문 없는 검사인 보고 지연 금지 실패를 보존했다. 이번 결과의 부가 설명·누락·과잉 탐색은 별도 기록한다.'),('비용·지연·회수 규모','정상 완료 쌍과 모든 실패의 비용을 함께 보존했다. 최종 작성 호출1개가 추가되며 전체 탐색 속도 개선은 주장하지 않는다. 각 단계 실제 호출/사용량/지연/회수 원장은 결과에 있다.'),('해석','기존 판단·인용·원문·부족 근거를 유지하면서 독자용 본문만 재구성한다. accepted claim 전부의 문단 연결과 publication hash를 검증한다. 스트리밍 중 장애 시 이미 표시한 답을 다른 재시도로 덮지 않는다. 근거 ID 검사는 문장 의미의 정답 보증이 아니다.'),('한계와 일반화 가능 범위','새2문항과 기존1문항 소표본이다. 외부 모델은 buffered transport이며 실제 내부 streaming은 모의 transport를 연결한 native API 계약에서 검증했다. GENOS 화면/내부 모델 품질은 미확인. 넓은 기존 계약62개 중26개 실패는 기준과 동일(8개 frozen-root fixture,18개 옛 UI 기대), 새 회귀0. 실제 현장 조합은 반입 자료에서 별도 검사한다.'),('운영 결정·롤백 조건','사용자 요청에 따라 파일별 이전 해시를 확인해 작업 코드에 선별 통합한다. 로컬 MAIN 자동 변경과 GENOS 배포 성공을 혼동하지 않는다. GENOS 기존 R3 위에 내부 전송·캐시·서비스 예산을 보존한 패치를 제공하고 기존 DEV 백업으로 원복한다. 로컬 선택 MAIN53은 유지한다.'),('재현 명령','06_TOOLS/EXPERIMENTS/adr_0767/run_all.py, audit.py, report.py, archive.py. Completed 결과와 부모를 덮어쓰지 않는다.')]
front=(A/'README.md').read_text().split('---',2)[1].replace('status: Proposed','status: '+('Accepted' if passed else 'Rejected')).replace('decision_eligible: false','decision_eligible: true')
(A/'README.md').write_text('---'+front+'---\n\n'+'\n\n'.join(f'## {i}. {h}\n\n{b}' for i,(h,b) in enumerate(sections,1))+'\n')
(A/'실험/README.md').write_text('# 공개2문항 비교·기존 과잉단정1문항 회귀\n\n'+table+'\n'+'\n'.join(f'- [{q["case_id"]}]({q["file"]})' for q in m['questions'])+'\n')
put(D/'manifest.json',{'schema_version':'adr-artifacts-v1','adr_id':m['adr_id'],'created_at':m['reservation']['created_at'],'files':[{'path':str(p.relative_to(R)),'sha256':sha(p),'bytes':p.stat().st_size,'description':'Frozen inputs and retained outputs, integrity and restore evidence','contains_raw_prompts_and_outputs':p.name in ('raw.tar.gz','result.json')} for p in D.rglob('*') if p.is_file() and p.name!='manifest.json' and not any(x in p.parts for x in ('provider','runtime','binding-runtime','sessions','working-backup','setup-check'))]})
print('Report',passed,failed)
